static LEXER_DFA_CELL: OnceLock<CompiledLexerDfa> = OnceLock::new();

/// Ahead-of-time lexer DFA tables compiled by antlr4-rust-gen, embedded as an
/// encoded blob so runtime startup only decodes them. Rebuilt from the ATN
/// instead when the embedded data comes from a different runtime version.
fn lexer_dfa() -> &'static CompiledLexerDfa {
    LEXER_DFA_CELL.get_or_init(|| {
        CompiledLexerDfa::from_encoded(LEXER_DFA_DATA)
            .unwrap_or_else(|| CompiledLexerDfa::compile(atn()))
    })
}

#[derive(Clone, Debug)]
pub struct RustLexer<I, H = antlr4_runtime::NoSemanticHooks>
where
    I: CharStream,
    H: antlr4_runtime::SemanticHooks,
{
    base: BaseLexer<I>,
    hooks: H,
}

impl<I> RustLexer<I, antlr4_runtime::NoSemanticHooks>
where
    I: CharStream,
{
    pub fn new(input: I) -> Self {
        Self::with_hooks(input, antlr4_runtime::NoSemanticHooks)
    }
}

impl<I, H> RustLexer<I, H>
where
    I: CharStream,
    H: antlr4_runtime::SemanticHooks,
{
    pub fn with_hooks(input: I, hooks: H) -> Self {
        let grammar_metadata = metadata();
        let data = grammar_metadata.recognizer_data();
        Self { base: BaseLexer::new(input, data).with_shared_dfa(atn()), hooks }
    }



}



antlr4_runtime::__antlr4_rust_lexer_facade! {
    type: RustLexer<I, H>,
    fields: {
        base: base,
        hooks: hooks,
    },
    metadata: metadata,
    next_token(lexer, sink) {
        if H::ENABLES_LEXER_LIFECYCLE {
            antlr4_runtime::atn::lexer::next_token_compiled_with_semantic_dispatch(&mut lexer.base, sink, atn(), lexer_dfa(), &mut lexer.hooks, |_, _| false, |_, _| None, antlr4_runtime::UnknownSemanticPolicy::Error, |_, _, _| {})
        } else {
            antlr4_runtime::atn::lexer::next_token_compiled(&mut lexer.base, sink, atn(), lexer_dfa())
        }
    }
}
